 public static WorkflowDefinition.Target target(JsonNode n){if(n!=null&&n.has("kind")){if(n.has("mappingPin")){fields(n,Set.of("kind","schemaVersion","metricKey","mappingPin"));if(!text(n,"schemaVersion").equals("1.1"))throw new IllegalArgumentException();var pin=com.acme.opsweave.platform.telemetry.MetricMappingJson.pin(n.get("mappingPin"));if(pin==null)throw new IllegalArgumentException();return new WorkflowDefinition.Target(null,1,null,text(n,"kind"),pin,text(n,"metricKey"));}fields(n,Set.of("kind","schemaVersion"));if(!text(n,"schemaVersion").equals("1.0"))throw new IllegalArgumentException();return new WorkflowDefinition.Target(null,1,null,text(n,"kind"));}fields(n,Set.of("id","revision","digest"));return new WorkflowDefinition.Target(text(n,"id"),integer(n,"revision",null),text(n,"digest"));}
