 public static WorkflowDefinition.Source source(JsonNode n){fields(n,Set.of("kind","instanceId","configuration","metric","log"));WorkflowDefinition.ConfigurationPin pin=null;if(n.has("configuration")){var c=n.get("configuration");fields(c,Set.of("sourceId","revision","digest"));String id=text(c,"sourceId");if(!id.matches("[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}"))throw new IllegalArgumentException();pin=new WorkflowDefinition.ConfigurationPin(UUID.fromString(id),integer(c,"revision",null),text(c,"digest"));}WorkflowMetricSourcePin metric=null;if(n.has("metric")){var m=n.get("metric");fields(m,Set.of("inspectionId","itemId","hostId","sourceKey","sourceUnit","sourceValueType","digest"));metric=new WorkflowMetricSourcePin(SourceConnectionJson.uuid(m,"inspectionId"),text(m,"itemId"),text(m,"hostId"),text(m,"sourceKey"),emptyText(m,"sourceUnit"),text(m,"sourceValueType"),text(m,"digest"));}WorkflowLogSourcePin log=null;if(n.has("log")){var m=n.get("log");fields(m,Set.of("inspectionId","itemId","hostId","sourceKey","sourceUnit","sourceValueType","digest"));log=new WorkflowLogSourcePin(SourceConnectionJson.uuid(m,"inspectionId"),text(m,"itemId"),text(m,"hostId"),text(m,"sourceKey"),emptyText(m,"sourceUnit"),text(m,"sourceValueType"),text(m,"digest"));}return new WorkflowDefinition.Source(text(n,"kind"),text(n,"instanceId"),pin,metric,log);}
